import{_ as t,o as a,c as r,ag as i}from"./chunks/framework.B3IQijK_.js";const g=JSON.parse('{"title":"Test in Strategy Lab","description":"Build, plan, run, judge, and promote durable Trading Office strategy experiments through TradingView.","frontmatter":{"title":"Test in Strategy Lab","description":"Build, plan, run, judge, and promote durable Trading Office strategy experiments through TradingView.","outline":2,"head":[["link",{"rel":"canonical","href":"https://tradecli.in/wiki/trading-office/strategy-lab"}]]},"headers":[],"relativePath":"trading-office/strategy-lab.md","filePath":"trading-office/strategy-lab.md"}'),n={name:"trading-office/strategy-lab.md"};function o(s,e,d,l,h,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="test-in-strategy-lab" tabindex="-1">Test in Strategy Lab <a class="header-anchor" href="#test-in-strategy-lab" aria-label="Permalink to &quot;Test in Strategy Lab&quot;">​</a></h1><p>Strategy Lab turns a Trading Office hypothesis into a reproducible experiment. AI helps express the idea and interpret the outcome; compiled code, stored plans, persisted jobs, and one machine-owned judge control what actually ran and what verdict it earned.</p><p>The current <code>/backtest</code> menu is labeled <strong>Backtest Lab</strong>. This guide uses <strong>Strategy Lab</strong> for the complete BUILD → PLAN → RUN → JUDGE → PROMOTE workflow exposed through that menu.</p><h2 id="start-an-experiment" tabindex="-1">Start an experiment <a class="header-anchor" href="#start-an-experiment" aria-label="Permalink to &quot;Start an experiment&quot;">​</a></h2><p>Use either verified entry point:</p><ul><li>Open <code>/ideas</code>, select a captured idea, and choose <strong>Send to Lab</strong>.</li><li>Run <code>/backtest</code> and choose <strong>New experiment</strong>.</li></ul><p>The second path asks you to describe the experiment. If a required choice such as the universe or entry rule cannot be resolved safely, the workflow asks one focused clarification instead of guessing.</p><h2 id="the-five-stage-contract" tabindex="-1">The five-stage contract <a class="header-anchor" href="#the-five-stage-contract" aria-label="Permalink to &quot;The five-stage contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Contract</th></tr></thead><tbody><tr><td><strong>BUILD</strong></td><td>Produce or restore a compiled strategy and fingerprint its exact implementation</td></tr><tr><td><strong>PLAN</strong></td><td>Resolve and lock the complete experiment before computation begins</td></tr><tr><td><strong>RUN</strong></td><td>Execute bounded chunks and persist every completed result</td></tr><tr><td><strong>JUDGE</strong></td><td>Apply one deterministic promising, rejected, or inconclusive verdict</td></tr><tr><td><strong>PROMOTE</strong></td><td>Freeze a promising result into a strategy version and propose paper deployment</td></tr></tbody></table><h2 id="build-—-make-the-idea-testable" tabindex="-1">BUILD — make the idea testable <a class="header-anchor" href="#build-—-make-the-idea-testable" aria-label="Permalink to &quot;BUILD — make the idea testable&quot;">​</a></h2><p>tradecli is the source of truth for strategy implementations; the TradingView chart is the render and simulation target. BUILD follows one of two paths:</p><ul><li><strong>Reuse</strong> a matching Strategy Library version and restore its saved Pine implementation.</li><li><strong>Author</strong> a complete Pine strategy for a new hypothesis.</li></ul><p>The strategy is compiled on TradingView. The build gate then verifies that the compiled script exposes the inputs the experiment expects to fix or sweep, returns the actual input catalogue, and fingerprints the result.</p><p>The workflow does not silently test whichever strategy happened to be open on the chart. On first setup, TradingView may expose one manual <strong>Add to chart</strong> step; after that, the build gate verifies the compiled strategy again.</p><h2 id="plan-—-approve-the-exact-experiment" tabindex="-1">PLAN — approve the exact experiment <a class="header-anchor" href="#plan-—-approve-the-exact-experiment" aria-label="Permalink to &quot;PLAN — approve the exact experiment&quot;">​</a></h2><p>PLAN resolves and persists a preview containing:</p><ul><li>the pre-test hypothesis;</li><li>fixed and swept parameters;</li><li>symbols and candle timeframes;</li><li>historical horizon or custom date range;</li><li>validation method;</li><li>commission and slippage assumptions;</li><li>ranking metric and minimum trade count;</li><li>finalist, cell, and chunk counts;</li><li>warnings and estimated run time.</li></ul><p>The native confirmation dialog starts that exact stored plan only when you approve it. If the strategy fingerprint or any experiment field changes, the plan must be created and approved again.</p><div class="tip custom-block"><p class="custom-block-title">Read the warning line</p><p>Zero costs, a parameter sweep without validation, type or range mismatches, and a grid near the cell limit are surfaced before approval because each can change how much confidence the result deserves.</p></div><h2 id="choose-a-validation-method" tabindex="-1">Choose a validation method <a class="header-anchor" href="#choose-a-validation-method" aria-label="Permalink to &quot;Choose a validation method&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>How it behaves</th></tr></thead><tbody><tr><td><strong>None</strong></td><td>Runs the requested experiment without a chronological validation split</td></tr><tr><td><strong>Holdout</strong></td><td>Selects candidates on an earlier training period, then evaluates finalists on a later period</td></tr><tr><td><strong>Walk-forward</strong></td><td>Repeats expanding training windows followed by successive unseen test windows</td></tr></tbody></table><p>Test windows do not participate in the initial parameter search. Current promotion ranking evaluates the selected finalists using later history, so describe the outcome as <strong>test-informed selection</strong>, not as a final untouched estimate. Any change inspired by later results belongs in a new hypothesis and job.</p><h2 id="run-—-persisted-resumable-evidence" tabindex="-1">RUN — persisted, resumable evidence <a class="header-anchor" href="#run-—-persisted-resumable-evidence" aria-label="Permalink to &quot;RUN — persisted, resumable evidence&quot;">​</a></h2><p>RUN divides the full parameter × symbol × timeframe plan into bounded chunks. Each completed chunk is stored in the local Trading Office record before the next begins. Status and results come from that stored job, not from model memory.</p><p>In a Trading Office pane, the workflow heartbeat can continue the next due chunk automatically. This deterministic continuation works in both Guided and Autonomous · Paper trading modes. A temporary TradingView failure is retried with backoff; it does not require the agent to invent progress.</p><p>Open <strong>Backtest Lab → Jobs</strong> for:</p><ul><li><strong>Status</strong> — persisted stage and progress, without AI.</li><li><strong>Results</strong> — specification, leaderboard, validation, and verdict, without AI.</li><li><strong>Interpret</strong> — an optional AI reading of the stored results.</li><li><strong>Cancel</strong> — stop a running job and keep its completed chunks.</li></ul><h2 id="judge-—-one-machine-verdict" tabindex="-1">JUDGE — one machine verdict <a class="header-anchor" href="#judge-—-one-machine-verdict" aria-label="Permalink to &quot;JUDGE — one machine verdict&quot;">​</a></h2><p>JUDGE returns exactly one of:</p><ul><li><strong>Promising</strong> — eligible for promotion.</li><li><strong>Rejected</strong> — the recorded evidence does not pass the gate.</li><li><strong>Inconclusive</strong> — the evidence is insufficient or unreliable.</li></ul><p>AI can explain what survived, what degraded, how costs affected the answer, and what to test next. It cannot override the verdict or mark pipeline stages complete.</p><h2 id="promote-—-freeze-then-approve" tabindex="-1">PROMOTE — freeze, then approve <a class="header-anchor" href="#promote-—-freeze-then-approve" aria-label="Permalink to &quot;PROMOTE — freeze, then approve&quot;">​</a></h2><p>Only a completed job with a promising verdict can be promoted. Promotion creates:</p><ol><li>a validated strategy version containing the frozen implementation, parameters, exits, universe, fingerprint, lineage, and evidence links; and</li><li>a proposed <strong>paper</strong> deployment containing its risk limits.</li></ol><p>After the promising verdict appears, ask the Trading Office pane to promote that completed job. Rejected and inconclusive jobs stay available as evidence but cannot be promoted.</p><p>Use <strong>Backtest Lab → Approvals</strong> to inspect and approve or reject the proposal. Approval is attributed to the active employee, and the evidence gate is checked again. Rejection stops the deployment proposal while preserving the strategy version and experiment evidence.</p><p>Approval records who authorized paper use and preserves the deployment decision. It does not start an automatic strategy-version execution runtime. Open <code>/strategies</code> to inspect the version and create the current risk-sized, reviewable paper ticket from its stored universe, exit rules, and risk limits.</p><h2 id="what-ai-owns—and-what-it-does-not" tabindex="-1">What AI owns—and what it does not <a class="header-anchor" href="#what-ai-owns—and-what-it-does-not" aria-label="Permalink to &quot;What AI owns—and what it does not&quot;">​</a></h2><table tabindex="0"><thead><tr><th>AI helps with</th><th>Deterministic systems own</th></tr></thead><tbody><tr><td>Shaping the hypothesis</td><td>Compiled strategy fingerprint</td></tr><tr><td>Authoring or restoring Pine</td><td>Immutable plan and approval</td></tr><tr><td>Explaining results</td><td>Chunk progress and stored cells</td></tr><tr><td>Suggesting a next experiment</td><td>Leaderboard and machine verdict</td></tr><tr><td>Discussing tradeoffs</td><td>Promotion and deployment state transitions</td></tr></tbody></table><h2 id="if-the-workflow-stops" tabindex="-1">If the workflow stops <a class="header-anchor" href="#if-the-workflow-stops" aria-label="Permalink to &quot;If the workflow stops&quot;">​</a></h2><ul><li><strong>TradingView is unavailable</strong> — keep the existing job. Temporary connection failures retry with backoff; inspect <strong>Backtest Lab → Jobs → Status</strong> before doing anything else.</li><li><strong>BUILD waits at the chart</strong> — complete the TradingView <strong>Add to chart</strong> action when it appears, then allow the build gate to verify the compiled strategy.</li><li><strong>The plan is rejected or changed</strong> — create and approve a new plan. An approved plan is not edited in place.</li><li><strong>A job is no longer needed</strong> — use <strong>Jobs → Cancel</strong>. Completed chunks remain attached to the experiment record.</li></ul><p>See <a href="/trading-sandbox-website-preview/wiki/getting-started/tradingview-setup">Connect TradingView</a> for the Desktop connection path.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li>Follow the complete workflow → <a href="./quickstart">Your First Strategy</a></li><li>Start with a cleaner claim → <a href="./ideas">Research and Ideas</a></li><li>Compare paper behavior with the backtest → <a href="./review">Review and Improve</a></li><li>Look up lifecycle terms → <a href="./concepts">Concepts and Terminology</a></li></ul>',44)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
